interface SlideDownloadButtonProps {
  title: string;
  fileUrl: string;
  fileName: string;
}

const SlideDownloadButton: React.FC<SlideDownloadButtonProps> = ({ title, fileUrl, fileName }) => {
  const [dragProgress, setDragProgress] = useState<number>(0);
  const [isCompleted, setIsCompleted] = useState<boolean>(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef<boolean>(false);

  const startDrag = () => {
    if (isCompleted) return;
    isDragging.current = true;
  };

  const onDrag = (clientX: number) => {
    if (!isDragging.current || !containerRef.current || isCompleted) return;
    const rect = containerRef.current.getBoundingClientRect();
    const knobWidth = 48; // Lebar tombol (48px)
    const maxDrag = rect.width - knobWidth - 8;
    const currentPos = clientX - rect.left - knobWidth / 2;
    const progress = Math.min(Math.max(currentPos / maxDrag, 0), 1);

    setDragProgress(progress * 100);

    if (progress >= 0.95) {
      triggerDownload();
    }
  };

  const stopDrag = () => {
    if (!isDragging.current) return;
    isDragging.current = false;
    if (!isCompleted) {
      setDragProgress(0);
    }
  };

  const triggerDownload = () => {
    isDragging.current = false;
    setIsCompleted(true);
    setDragProgress(100);

    const link = document.createElement("a");
    link.href = fileUrl;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    setTimeout(() => {
      setIsCompleted(false);
      setDragProgress(0);
    }, 2500);
  };

  return (
    <div
      ref={containerRef}
      onMouseMove={(e) => onDrag(e.clientX)}
      onMouseUp={stopDrag}
      onMouseLeave={stopDrag}
      onTouchMove={(e) => onDrag(e.touches[0].clientX)}
      onTouchEnd={stopDrag}
      // "group/slider" mengesan apabila keseluruhan kawasan butang disentuh/di-hover
      className="group/slider relative flex items-center w-full sm:w-72 h-14 p-1 rounded-2xl bg-gradient-to-b from-[#121826] to-[#0A0E17] border border-[#D4AF37]/30 shadow-[0_4px_20px_rgba(0,0,0,0.5)] hover:shadow-[0_4px_25px_rgba(212,175,55,0.15)] hover:border-[#D4AF37]/60 transition-all duration-300 select-none overflow-hidden cursor-pointer"
    >
      {/* Warna Latar Leret */}
      <div
        className="absolute inset-y-0 left-0 bg-gradient-to-r from-[#B8860B]/20 via-[#D4AF37]/40 to-amber-300/50 transition-all duration-75 rounded-xl pointer-events-none"
        style={{ width: `${Math.max(dragProgress, 5)}%` }}
      />

      {/* Teks & Ikon Tengah */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none px-6">
        <div className="flex items-center space-x-2 transition-opacity duration-200">
          <BookOpen className="w-4 h-4 text-[#D4AF37] group-hover/slider:scale-110 transition-transform duration-300" />
          <span className="text-xs sm:text-sm font-bold tracking-wide text-slate-300 group-hover/slider:text-white transition-colors duration-300">
            {isCompleted ? "DOWNLOADING..." : title}
          </span>
          {!isCompleted && (
            <div className="flex items-center -space-x-1 text-slate-600 group-hover/slider:text-[#D4AF37] transition-colors duration-300">
              <ChevronRight className="w-3.5 h-3.5 animate-pulse" />
              <ChevronRight className="w-3.5 h-3.5 animate-pulse delay-150" />
            </div>
          )}
        </div>
      </div>

      {/* Tombol Leret (Knob) */}
      <div
        onMouseDown={startDrag}
        onTouchStart={startDrag}
        style={{
          transform: `translateX(${(dragProgress / 100) * ((containerRef.current?.offsetWidth || 288) - 56)}px)`,
          transition: isDragging.current ? "none" : "transform 0.3s ease-out",
        }}
        className={`relative z-10 flex items-center justify-center w-12 h-12 rounded-xl cursor-grab active:cursor-grabbing shadow-[0_2px_10px_rgba(0,0,0,0.6)] border transition-all duration-300 ${
          isCompleted
            ? "bg-emerald-500 border-emerald-300 text-white"
            : "bg-gradient-to-br from-[#F5D77F] via-[#D4AF37] to-[#8C6B1C] border-[#FFF5C0]/60 text-slate-950 group-hover/slider:shadow-[0_0_20px_rgba(212,175,55,0.7)]"
        }`}
      >
        {isCompleted ? (
          <Check className="w-5 h-5 stroke-[3] scale-110 transition-transform duration-300" />
        ) : (
          /* DI SINI PERUBAHANNYA: Ikon berputar (-rotate-90) dan sedikit membesar (scale-110) apabila di-hover atau dileret */
          <Download
            className={`w-5 h-5 transition-transform duration-300 ease-out ${
              dragProgress > 0
                ? "-rotate-90 scale-110"
                : "group-hover/slider:-rotate-90 group-hover/slider:scale-110"
            }`}
          />
        )}
      </div>
    </div>
  );
};
